BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(19);
SELECT has_table('public', 'lords_day_notes', 'notes exist');
SELECT has_table('public', 'lords_day_cards', 'cards exist');
SELECT columns_are('public', 'lords_day_notes', ARRAY['id','user_id','service_date','passage_ref','sermon_title','preacher','church','extracted_text','created_at','updated_at','deleted_at','change_id'], 'note columns');
SELECT columns_are('public', 'lords_day_cards', ARRAY['id','note_id','user_id','kind','body','verse_ref','attribution','palette','position','edited_by_user','created_at','updated_at','deleted_at','change_id'], 'card columns');
INSERT INTO auth.users (id, email) VALUES ('aaaaaaaa-0000-0000-0000-000000000001','a@example.test'), ('bbbbbbbb-0000-0000-0000-000000000002','b@example.test');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-0000-0000-0000-000000000001","role":"authenticated"}', true);
SELECT lives_ok($$ INSERT INTO public.lords_day_notes (id,user_id,service_date) VALUES ('a0000000-0000-0000-0000-000000000001',auth.uid(),'2026-11-15') $$, 'owner inserts note');
SELECT lives_ok($$ INSERT INTO public.lords_day_cards (id,note_id,user_id,kind,body,position) VALUES ('a0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001',auth.uid(),'key_point','point',0) $$, 'owner inserts card');
SELECT throws_ok($$ INSERT INTO public.lords_day_cards (id,note_id,user_id,kind,body,position) VALUES ('a0000000-0000-0000-0000-000000000003','a0000000-0000-0000-0000-000000000001',auth.uid(),'other','bad',1) $$, '23514', NULL, 'invalid kind rejected');
SELECT lives_ok($$ INSERT INTO public.lords_day_cards (id,note_id,user_id,kind,body,position) VALUES ('a0000000-0000-0000-0000-000000000004','a0000000-0000-0000-0000-000000000001',auth.uid(),'quote','quote',1), ('a0000000-0000-0000-0000-000000000005','a0000000-0000-0000-0000-000000000001',auth.uid(),'verse','verse',2) $$, 'other valid kinds accepted');
SELECT set_config('request.jwt.claims', '{"sub":"bbbbbbbb-0000-0000-0000-000000000002","role":"authenticated"}', true);
SELECT is_empty($$ SELECT 1 FROM public.lords_day_notes $$, 'other user sees no notes');
SELECT is_empty($$ SELECT 1 FROM public.lords_day_cards $$, 'other user sees no cards');
SELECT throws_ok($$ INSERT INTO public.lords_day_notes (id,user_id,service_date) VALUES ('b0000000-0000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000001','2026-11-15') $$, '42501', NULL, 'forged note rejected');
SELECT throws_ok($$ INSERT INTO public.lords_day_cards (id,note_id,user_id,kind,body,position) VALUES ('b0000000-0000-0000-0000-000000000003','a0000000-0000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000001','quote','forged',0) $$, '42501', NULL, 'forged card rejected');
SELECT throws_ok($$ INSERT INTO public.lords_day_cards (id,note_id,user_id,kind,body,position) VALUES ('b0000000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001',auth.uid(),'quote','bad',0) $$, '23503', NULL, 'cross-user note link rejected');
UPDATE public.lords_day_notes SET extracted_text = 'hacked' WHERE id = 'a0000000-0000-0000-0000-000000000001';
DELETE FROM public.lords_day_cards WHERE id = 'a0000000-0000-0000-0000-000000000002';
SELECT set_config('request.jwt.claims', '{"sub":"aaaaaaaa-0000-0000-0000-000000000001","role":"authenticated"}', true);
SELECT is((SELECT extracted_text FROM public.lords_day_notes WHERE id = 'a0000000-0000-0000-0000-000000000001'), NULL, 'other user cannot update note');
SELECT is((SELECT count(*)::int FROM public.lords_day_cards), 3, 'other user cannot delete cards');
CREATE TEMP TABLE original_note AS SELECT change_id, updated_at FROM public.lords_day_notes WHERE id = 'a0000000-0000-0000-0000-000000000001';
UPDATE public.lords_day_notes SET extracted_text = 'stale', updated_at = '2000-01-01' WHERE id = 'a0000000-0000-0000-0000-000000000001';
SELECT ok((SELECT n.extracted_text IS NULL AND n.change_id = o.change_id FROM public.lords_day_notes n, original_note o WHERE n.id = 'a0000000-0000-0000-0000-000000000001'), 'stale update is ignored');
UPDATE public.lords_day_notes SET deleted_at = now(), updated_at = clock_timestamp() WHERE id = 'a0000000-0000-0000-0000-000000000001';
SELECT ok((SELECT deleted_at IS NOT NULL AND updated_at >= created_at FROM public.lords_day_notes WHERE id = 'a0000000-0000-0000-0000-000000000001'), 'soft delete remains visible for sync');
SELECT ok((SELECT n.change_id > o.change_id FROM public.lords_day_notes n, original_note o WHERE n.id = 'a0000000-0000-0000-0000-000000000001'), 'accepted update advances cursor');
SELECT ok((SELECT n.updated_at > o.updated_at FROM public.lords_day_notes n, original_note o WHERE n.id = 'a0000000-0000-0000-0000-000000000001'), 'writer timestamp is preserved');
SELECT * FROM finish();
ROLLBACK;
